INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES
(1521,0,0,'Save me from the cold!',12,0,100,0,0,0,39007,0,'Gretchen Dedmar'),
(1521,1,0,'So cold...',12,0,100,0,0,0,39009,0,'Gretchen Dedmar'),
(1934,0,0,'Get out of my kitchen!',12,0,100,0,0,0,44544,0,'Tirisfal Farmer'),
(1934,0,1,'Get back, $r!',12,0,100,0,0,0,44542,0,'Tirisfal Farmer'),
(1934,0,2,'No, no, no... you took my family, but you won\'t take my land!',12,0,100,0,0,0,44541,0,'Tirisfal Farmer'),
(1934,0,3,'Why won\'t you leave us alone?',12,0,100,0,0,0,44543,0,'Tirisfal Farmer'),
(38895,0,0,'No. You\'re lying! My father will protect me!',12,0,100,0,0,0,49337,0,'Lilian'),
(38910,0,0,'You don\'t understand... I CAN\'T be undead! Not me, not now...',12,0,100,22,0,0,38982,0,'Lilian'),
(38999,0,0,'Yes, my... wait, be quiet! I hear the lieutenant approaching.',12,0,100,0,0,0,39000,0,'Lilian'),
(38999,1,0,'Gebler, you came! What did he say?',12,0,100,1,0,0,38994,0,'Lilian'),
(38999,2,0,'What? NO! This can\'t be! Gebler, you know me... we were friends once!',12,0,100,1,0,0,38996,0,'Lilian'),
(38999,3,0,'Gebler, father, why would you...',12,0,100,1,0,0,39001,0,'Lilian'),
(38999,4,0,'The world of the living may have turned its back on me, but I\'m no damned Scourge. Just go.',12,0,100,1,0,0,38999,0,'Lilian'),
(39002,0,0,'The time has come, my little captive... word has come back from your father.',12,0,100,0,0,0,38993,0,'Gebler'),
(39002,1,0,'High Priest Voss denounces you as a daughter. He\'s ordered that you be executed immediately.',12,0,100,1,0,0,38995,0,'Gebler'),
(39002,2,0,'The High Priest sends his regrets. He had hoped that one day you would be a powerful weapon against our enemies.',12,0,100,1,0,0,38997,0,'Gebler'),
(39002,3,0,'Unfortunately, you were too dangerous in life, and you\'re far too dangerous in undeath. I will enjoy killing you, you Scourged witch...',12,0,100,1,0,0,38998,0,'Gebler'),
(49230,0,0,'Who are you calling a monster? You\'re the monster! I\'m just a man who died.',12,0,100,1,0,0,49345,0,'Marshal'),
(49231,0,0,'I see. Well then, let\'s get to work, $n! The Dark Lady needs us, right?',12,0,100,1,0,0,49351,0,'Valdred'),
(49231,1,0,'Valdred Moray, reporting for duty, sir!',14,0,100,1,0,0,49408,0,'Valdred'),
(49337,0,0,'Hello again.',12,0,100,3,0,0,49455,0,'Darnell'),
(49337,1,0,'I know the way to Deathknell. Come with me!',12,0,100,273,0,0,49456,0,'Darnell'),
(49337,2,0,'Good, you\'re still here. Now, where\'s Deathguard Saltain?',12,0,100,1,0,0,49457,0,'Darnell'),
(49337,3,0,'Ah, here he is.',12,0,100,1,0,0,49458,0,'Darnell'),
(49337,4,0,'Let\'s get moving, $n. Saltain said that we\'d fine some corpses up here.',12,0,100,1,0,0,49459,0,'Darnell'),
(49337,5,0,'I think I see some corpses up ahead. Let\'s go, $n! You do the searching and fighting. I\'ll do the lifting.',12,0,100,0,0,0,49460,0,'Darnell');
